public class Main {
    static final int MAXN = 2000;
    static final int INF = 1000000000;
    static final int[] dr = {0, -1, 0, 1};
    static final int[] dc = {1, 0, -1, 0};
    static int[][] gridA = new int[12][12];
    static int[][] gridB = new int[12][12];
    static int[][] distF = new int[12][12];
    static int[][] a = new int[12][12];
    static int[][] b = new int[12][12];
    static int[][] f = new int[12][12];
    static int n, t;
    static int m = 0, o = 0, sr, sc;
    static java.util.List<Integer>[] edges = new java.util.ArrayList[2000];
    static java.util.List<Integer>[][] cellGroups = new java.util.ArrayList[12][12];

    static {
        for (int i = 0; i < 2000; i++) {
            edges[i] = new java.util.ArrayList<>();
        }
        for (int i = 0; i < 12; i++) {
            for (int j = 0; j < 12; j++) {
                cellGroups[i][j] = new java.util.ArrayList<>();
            }
        }
    }

    static class HungarianMatch {
        int totalMatches;
        int[] matchPartner = new int[MAXN];
        int[] reversePartner = new int[MAXN];
        int[] used = new int[MAXN];

        public int findMaxMatching(int n, java.util.List<Integer>[] adj) {
            totalMatches = 0;
            java.util.Arrays.fill(matchPartner, -1);
            java.util.Arrays.fill(reversePartner, -1);
            for (int i = 0; i < n; i++) {
                java.util.Arrays.fill(used, 0);
                if (tryMatch(i, adj)) totalMatches++;
            }
            return totalMatches;
        }

        private boolean tryMatch(int u, java.util.List<Integer>[] adj) {
            for (int v : adj[u]) {
                if (used[v] == 0) {
                    used[v] = 1;
                    if (reversePartner[v] < 0 || tryMatch(reversePartner[v], adj)) {
                        matchPartner[u] = v;
                        reversePartner[v] = u;
                        return true;
                    }
                }
            }
            return false;
        }
    }

    public static void floodFill(int r, int c) {
        java.util.Queue<Integer> qRow = new java.util.LinkedList<>();
        java.util.Queue<Integer> qCol = new java.util.LinkedList<>();
        for (int i = 0; i < 12; i++) {
            for (int j = 0; j < 12; j++) {
                distF[i][j] = -1;
            }
        }
        qRow.add(r);
        qCol.add(c);
        distF[r][c] = 0;
        while (!qRow.isEmpty()) {
            int rr = qRow.poll();
            int cc = qCol.poll();
            for (int i = 0; i < 4; i++) {
                int nr = rr + dr[i];
                int nc = cc + dc[i];
                if (nr >= 0 && nr < n && nc >= 0 && nc < n && gridA[nr][nc] >= 0 && distF[nr][nc] < 0) {
                    distF[nr][nc] = distF[rr][cc] + 1;
                    qRow.add(nr);
                    qCol.add(nc);
                }
            }
        }
    }

    public static void assignMarks(int r, int c, int count) {
        int[][] visitedV = new int[12][12];
        java.util.Queue<Integer> qRow = new java.util.LinkedList<>();
        java.util.Queue<Integer> qCol = new java.util.LinkedList<>();
        for (int i = 0; i < 12; i++) {
            for (int j = 0; j < 12; j++) {
                visitedV[i][j] = -1;
            }
        }
        qRow.add(r);
        qCol.add(c);
        visitedV[r][c] = 0;
        while (!qRow.isEmpty()) {
            int rr = qRow.poll();
            int cc = qCol.poll();
            if (visitedV[rr][cc] > Math.min(t, distF[rr][cc])) continue;
            for (int groupIdx : cellGroups[rr][cc]) {
                for (int i = 0; i < count; i++) {
                    edges[n + i].add(groupIdx);
                }
            }
            if (visitedV[rr][cc] == Math.min(t, distF[rr][cc])) continue;
            for (int i = 0; i < 4; i++) {
                int nr = rr + dr[i];
                int nc = cc + dc[i];
                if (nr >= 0 && nr < n && nc >= 0 && nc < n && gridA[nr][nc] >= 0 && visitedV[nr][nc] < 0) {
                    visitedV[nr][nc] = visitedV[rr][cc] + 1;
                    qRow.add(nr);
                    qCol.add(nc);
                }
            }
        }
        n += count;
    }

    public static void main(String[] args) throws java.io.IOException {
        java.util.Scanner sc = new java.util.Scanner(System.in);
        m = 0;
        o = 0;
        n = sc.nextInt();
        t = sc.nextInt();
        sc.nextLine();
        for (int i = 0; i < 12; i++) {
            for (int j = 0; j < 12; j++) {
                gridA[i][j] = -1;
                gridB[i][j] = -1;
                f[i][j] = -1;
            }
        }
        String line = sc.nextLine();
        for (int i = 0; i < n; i++) {
            line = sc.nextLine();
            for (int j = 0; j < n; j++) {
                char ch = line.charAt(j);
                if (ch >= '0' && ch <= '9') {
                    gridA[i][j] = ch - '0';
                }
                if (ch == 'Z') {
                    sr = i;
                    sc = j;
                }
            }
        }
        floodFill(sr, sc);
        line = sc.nextLine();
        for (int i = 0; i < n; i++) {
            line = sc.nextLine();
            for (int j = 0; j < n; j++) {
                char ch = line.charAt(j);
                if (ch >= '0' && ch <= '9') {
                    gridB[i][j] = ch - '0';
                }
                for (int k = 0; k < gridB[i][j]; k++) {
                    cellGroups[i][j].add(o++);
                }
            }
        }
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (f[i][j] < 0) f[i][j] = INF;
            }
        }
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (gridA[i][j] > 0) {
                    assignMarks(i, j, gridA[i][j]);
                }
            }
        }
        HungarianMatch matcher = new HungarianMatch();
        System.out.println(matcher.findMaxMatching(m, edges));
    }
}
